insert into restaurant_settings(id,phone,map_url,social,schedule,dine_enabled,tables_list,logo_url,cover_url,hero_url,content) values(1,'0558538845','https://maps.app.goo.gl/9gBNwRVCuMNunmEf6?g_st=ic','{"fb": "https://www.facebook.com/share/18QSbq1q47/?mibextid=wwXIfr", "ig": "https://www.instagram.com/lantica_forno_medea26", "tt": "https://www.tiktok.com/@lanticaforno?_r=1&_t=ZS-9AkoOToWvi9"}'::jsonb,'[{"open": "11:30", "close": "23:30", "closed": false}, {"open": "11:30", "close": "23:30", "closed": false}, {"open": "11:30", "close": "23:30", "closed": false}, {"open": "11:30", "close": "23:30", "closed": false}, {"open": "11:30", "close": "23:30", "closed": false}, {"open": "15:00", "close": "23:30", "closed": false}, {"open": "11:30", "close": "23:30", "closed": false}]'::jsonb,true,'1-17','images/logo.png','images/cover.jpg','images/hero.jpg','{"name": "لانتيكا", "nameF": "L’Antica Forno Médéa", "city": "المدية", "cityF": "Médéa", "hours": "يوميًا 11:30 – 23:30", "hoursF": "Tous les jours 11h00 – 23h00", "addr": "طريق الجزائر، المدية", "addrF": "Route D’Alger, Médéa", "welcome": "من هنا تبدأ الحكاية", "welcomeF": "Soyez les bienvenus", "tagline": "نكهة تُحكى وطعم لا يُنسى", "taglineF": "Une saveur qui se raconte, un goût inoubliable", "about": "L’Antica \n\nUne Passion, Une Histoire, Une Saveur Inoubliable.\nمن المدية إلى كل محبي المذاق الأصيل، حكايتنا تبدأ بشغف تحضير البيتزا و المذاقات المفقودة، وتستمر بتقديم تجربة تجمع بين الجودة، النكهة المميزة وحسن الاستقبال.\nفي لانتيكا، نحن لا نقدّم مجرد وجبات، بل نصنع لحظات من المتعة في كل لقمة، من البيتزا المحضّرة بعناية إلى البرغر والساندويتشات والتاكوس، مع الحرص على إرضاء أذواق زبائننا وتقديم الأفضل لهم.\n\nL’Antica  نكهة تُحكى، وطعم لا يُنسى.", "aboutF": "L’Antica Forno\n\nUne Passion, Une Histoire, Une Saveur Inoubliable.\n\nÀ Médéa, L’Antica Forno est née d’une passion pour la cuisine et le plaisir de partager des saveurs authentiques.\n\nNous vous proposons une sélection gourmande de pizzas, burgers, sandwichs, tacos et plats savoureux, préparés avec soin pour vous offrir une expérience unique à chaque bouchée.\n\nBien plus qu’un restaurant, L’Antica Forno est un lieu où la qualité, la générosité et le goût se rencontrent pour transformer chaque repas en un moment de plaisir.\n\nL’Antica  Une saveur qui se raconte, un goût inoubliable.", "copy": "© L’Antica Forno 2026", "copyF": "L’Antica Forno 2026 ©", "dev": "Younes Kalache", "devUrl": "https://www.instagram.com/kalache.younes", "tabTitle": "L’Antica Forno Médéa", "tabTitleF": "L’Antica Forno Médéa", "theme": {"red": "#a4161a", "bg": "#0d0d0d", "card": "#1a1a1a", "txt": "#f5f5f5", "font": "Montserrat"}}'::jsonb) on conflict (id) do nothing;
